#include <bits/stdc++.h>using namespace std;#define int long long int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int n, m;    cin >> n >> m;    vector<int> v(n);    for (int i = 0; i < m; i++) {        int a, b;        cin >> a >> b;        v[a - 1] += 1;        v[b - 1] += 1;    }    sort(v.rbegin(), v.rend());    if (v[0] == n - 1 && v[1] == 1) {        cout << "star topology\n";    } else if (v[0] == 2 && v[n - 1] == 2) {        cout << "ring topology\n";    } else if (v[0] == 2 && v[n - 3] == 2 && v[n - 1] == 1 && v[n - 2] == 1) {        cout << "bus topology\n";    } else {        cout << "unknown topology\n";    }    return 0;}